window.docContents[113].resolve({"/Gamma-Function/___5___5-Functional-Relations/#LMLF-___-DLMF-with-Lean--Gamma-Function--___5___5-Functional-Relations--___5___5_LPAR_i_RPAR_-Recurrence":{"contents":"Source: DLMF §5.5(i).\n\n\\Gamma(z+1)=z\\Gamma(z).Away from the nonpositive integers, increasing the argument of the Gamma function by one\nmultiplies its value by the original argument. The formal statement keeps this ordinary\npointwise domain explicit because Mathlib assigns the value zero to Gamma at its poles.\n\n\\psi(z+1)=\\psi(z)+\\frac1z.On the same pole-free domain, the logarithmic derivative of Gamma gains the reciprocal term\n1/z when its argument is increased by one.\n\n","context":"LMLF · DLMF with Lean\u0009Gamma Function\u0009§5.5 Functional Relations","header":"§5.5(i) Recurrence","id":"/Gamma-Function/___5___5-Functional-Relations/#LMLF-___-DLMF-with-Lean--Gamma-Function--___5___5-Functional-Relations--___5___5_LPAR_i_RPAR_-Recurrence"}});